import SwiftUI
import UIKit

/// Heroicons-style 24x24 paths, the same set as the Android app. Outline icons
/// are stroked with round caps, solids filled.
struct SynkVector: Hashable {
    let paths: [String]
    var fill = false

    private static var cache: [SynkVector: CGPath] = [:]

    var cgPath: CGPath {
        if let p = SynkVector.cache[self] { return p }
        let combined = CGMutablePath()
        for d in paths { combined.addPath(SVGPathParser.parse(d)) }
        SynkVector.cache[self] = combined
        return combined
    }
}

extension SynkVector {
    /// A template image for system bars (tab bar items).
    func image(_ size: CGFloat = 24) -> UIImage {
        let r = UIGraphicsImageRenderer(size: CGSize(width: size, height: size))
        let img = r.image { c in
            let s = size / 24
            var t = CGAffineTransform(scaleX: s, y: s)
            guard let p = cgPath.copy(using: &t) else { return }
            let g = c.cgContext
            g.addPath(p)
            UIColor.white.set()
            if fill {
                g.fillPath(using: .evenOdd)
            } else {
                g.setLineWidth(1.75)
                g.setLineCap(.round)
                g.setLineJoin(.round)
                g.strokePath()
            }
        }
        return img.withRenderingMode(.alwaysTemplate)
    }
}

struct SynkIcon: View {
    let icon: SynkVector
    var size: CGFloat = 24
    var tint: Color = Theme.fg
    var stroke: CGFloat = 1.75

    init(_ icon: SynkVector, size: CGFloat = 24, tint: Color = Theme.fg, stroke: CGFloat = 1.75) {
        self.icon = icon; self.size = size; self.tint = tint; self.stroke = stroke
    }

    var body: some View {
        let path = icon.cgPath
        let fill = icon.fill
        Canvas { ctx, sz in
            let s = min(sz.width, sz.height) / 24
            var t = CGAffineTransform(scaleX: s, y: s)
            guard let scaled = path.copy(using: &t) else { return }
            if fill {
                ctx.fill(Path(scaled), with: .color(tint), style: FillStyle(eoFill: true))
            } else {
                ctx.stroke(Path(scaled), with: .color(tint), style: StrokeStyle(lineWidth: stroke, lineCap: .round, lineJoin: .round))
            }
        }
        .frame(width: size, height: size)
        .accessibilityHidden(true)
    }
}

